    # your code here
    pass

solution:
def longest_straight_run(route):
    if not route:
        return 0
    best = 1
    current = 1
    for i in range(1, len(route)):
        if route[i] == route[i - 1]:
            current += 1
            if current > best:
                best = current
        else:
            current = 1
    return best

